x = M_.params(8);
D = load('demo_paths_RoW.mat');    
y_start = 1970;
y_end   = 2070;
i0 = find(D.Year == y_start);
i1 = find(D.Year == y_end);
assert(~isempty(i0) && ~isempty(i1), 'Ano fora do intervalo do .mat');
Year_win          = D.Year(i0:i1);              
gamma_RoW_data    = D.gamma_RoW_path(i0:i1);    
phi_RoW_data      = D.phi_RoW_path(i0:i1);
gamma_RoW_start = gamma_RoW_data(1);            
gamma_RoW_end   = gamma_RoW_data(end);          
phi_RoW_start   = phi_RoW_data(1);
phi_RoW_end     = phi_RoW_data(end);
fprintf('WPP: gamma %.4f -> %.4f | phi %.4f -> %.4f\n', ...
        gamma_RoW_start, gamma_RoW_end, phi_RoW_start, phi_RoW_end);
%
% INITVAL instructions
%
options_.initval_file = false;
oo_.exo_steady_state(1) = gamma_RoW_start;
oo_.exo_steady_state(2) = phi_RoW_start;
oo_.steady_state(45)=oo_.exo_steady_state(1);
